// GetStoreApiProductSearchParams defines parameters for GetStoreApiProductSearch.
type GetStoreApiProductSearchParams struct {
	// Page Page number, starting at 1.
	Page *CriteriaPage `form:"page,omitempty" json:"page,omitempty"`

	// Limit Number of items per page.
	Limit *CriteriaLimit `form:"limit,omitempty" json:"limit,omitempty"`

	// Tag Filters by a product tag; `code` or `label` from `GET /store-api/v1/tag`.
	Tag *string `form:"tag,omitempty" json:"tag,omitempty"`

	// ProductIds Filter products by one or more product IDs. Pass multiple IDs as a comma-separated list, e.g. `<productId>,<productId>`. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/productIds`.
	ProductIds *CriteriaProductIds `form:"productIds,omitempty" json:"productIds,omitempty"`

	// Numbers Filter products by product number, EAN or manufacturer number (exact match, case-insensitive, spaces around a number are ignored), also of a unit in `variants`. The number of a packaging unit the shop does not offer lists its product, but without that unit in `variants`. Pass up to 100 different numbers as a comma-separated list, e.g. `1207,4251786202546,AST04689`, or repeat the parameter as `numbers[]=<number>` for numbers that contain a comma. Repeated numbers and empty entries are ignored; an empty value means no filter. More than 100 different numbers return `400` with `STROMBAUER_STORE_API__TOO_MANY_NUMBERS/numbers`.
	Numbers *string `form:"numbers,omitempty" json:"numbers,omitempty"`

	// CategoryId Filter products by one or more category IDs. Pass multiple IDs as a comma-separated list. Returns the products the category shows in its listing, including subcategories and categories filled by a product stream or a tag. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/categoryId`.
	CategoryId *CriteriaCategoryId `form:"categoryId,omitempty" json:"categoryId,omitempty"`

	// ManufacturerId Filter products by one or more manufacturer IDs. Pass multiple IDs as a comma-separated list. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/manufacturerId`.
	ManufacturerId *CriteriaManufacturerId `form:"manufacturerId,omitempty" json:"manufacturerId,omitempty"`

	// Properties Filter products by property values (the `id` of a value in `facets`). Pass multiple IDs as a comma-separated list. Values of the same property are combined with OR, values of different properties with AND: `properties=<11 kW>,<22 kW>,<3-phase>` returns products with 11 kW or 22 kW that are also 3-phase. `total` and the pages count the filtered products. An ID that is not a property value returns no products. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/properties`.
	Properties *CriteriaProperties `form:"properties,omitempty" json:"properties,omitempty"`

	// Sort Sort order of the list. A leading `-` sorts descending. The applied sort order is returned as `sort` in the response.
	//
	// With exactly one `categoryId` (an ID repeated in the list counts once) the category decides: `sortings.available` of the category in `GET /category` lists the allowed fields (each in both directions), and without `sort` the list is sorted by `sortings.default`. A value whose field the category does not offer returns `400` with `STROMBAUER_STORE_API__INVALID_SORTING`. Without `categoryId` or with several different IDs all values are allowed and the list is sorted by `-popularity` without `sort`.
	//
	// - `popularity`, `-popularity`: number of orders of the last 30 days that contain the product, from all customers and all order channels, without canceled orders. Each order counts once per product, regardless of quantity and unit. A set or bundle counts only for itself. `-popularity` lists the most ordered products first. The number is updated once a day and is not part of the response. Products with the same number are sorted like `-availableStock`, then by `id`.
	// - `name`, `-name`: product name.
	// - `price`, `-price`: price of the customer for one unit of the main variant (usually the piece), otherwise the list price. Products without price come last in both directions. Only for logged-in customers with a customer number that are unlocked for orders (not for a locked customer group such as „Blockiert“); otherwise `400` with `STROMBAUER_STORE_API__PRICE_SORTING_NOT_ALLOWED`.
	// - `availableStock`, `-availableStock`: availability. Descending lists products in stock first (larger stock of the base unit first), then products without stock but with a restock date (earliest date first), then products without stock and without restock date (stock 0 before negative stock). Ascending gives the reverse order.
	//
	// Any other value gives `400` with `STROMBAUER_STORE_API__INVALID_SORTING`.
	Sort *GetStoreApiProductSearchParamsSort `form:"sort,omitempty" json:"sort,omitempty"`
}

