type GetStoreApiStrombauerSalesOrdersParams struct {
	// Term Optional search term. Returns the orders of the customer, from any date, in which the term is part of the order number (`number`, e.g. `AUF26-9217`), the shop order number (`externalOrderNumber`), the reference (`reference`) or the article number or article name of a line item. Upper and lower case are ignored. Line items are matched by the article number and name recorded with the order; `items[].productNumber` and `items[].name` show the current shop data, which can differ slightly (e.g. `1723.STÜCK` is found by `1723`). Leading and trailing spaces are ignored; an empty term returns all orders as without the parameter.
	Term *string `form:"term,omitempty" json:"term,omitempty"`

	// Filter Optional filters (AG-721), several separated by commas (`filter=OPEN_INVOICES,ACTION_REQUIRED`) or as list (`filter[]=OPEN_INVOICES&filter[]=ACTION_REQUIRED`). With several filters an order must match all of them; combinable with `term` and `p`/`limit`. Filters run over all orders of the customer, from any date (an open invoice of last year is still open). `OPEN_INVOICES` „Offene Rechnungen“: at least one invoice with `state` `OPEN` (remaining amount > 0; canceled invoices never count); the payment state is as current as the last invoice sync from Business Central. `OPEN_DELIVERIES` „Offene Lieferungen“: BC still delivers the order and an article position (`type` `Item`) has an undelivered rest, `orderedQuantity` − `shippedQuantity` > 0 (nothing is canceled while BC still delivers), including orders nothing has been shipped of yet. Positions without `orderedQuantity` (orders not synchronised since 16.10.2026) do not count, because the rest is unknown. Once BC delivers nothing more, the rest is canceled (`canceledQuantity`) and the order no longer counts. `ACTION_REQUIRED` „Wartet auf dich“: the current status (the `status` of the section with `current: true`) is `WAITING_FOR_CUSTOMER`, `WAITING_FOR_PREPAYMENT` or `WAITING_FOR_CREDIT_LIMIT`. Values are upper case; blanks, tabs and line breaks around a value and empty values are ignored, an empty parameter means no filter. Any other value, also control characters, answers 400 `CUSTOMER__SALES_ORDER_INVALID_FILTER`.
	Filter *[]GetStoreApiStrombauerSalesOrdersParamsFilter `form:"filter,omitempty" json:"filter,omitempty"`

	// P Page number (starts at 1).
	P *int `form:"p,omitempty" json:"p,omitempty"`

	// Limit Number of orders per page (maximum 100).
	Limit *int `form:"limit,omitempty" json:"limit,omitempty"`
}

// GetStoreApiStrombauerSalesOrdersParamsFilter defines parameters for GetStoreApiStrombauerSalesOrders.
type GetStoreApiStrombauerSalesOrdersParamsFilter string

// GetStoreApiSearchParams defines parameters for GetStoreApiSearch.
type GetStoreApiSearchParams struct {
	// Term Search term. Without a term the result contains no products.
	Term *CriteriaTerm `form:"term,omitempty" json:"term,omitempty"`

	// Source Where the user typed the term: `suggest` for every request of a preview while typing, `results` for a search result page. Searches without `source` are not recorded and return `searchLogId: null`; leave it out for searches the user did not type, e.g. looking up item numbers. The value does not change the response.
	Source *GetStoreApiSearchParamsSource `form:"source,omitempty" json:"source,omitempty"`

	// Tag Filters by a product tag; `code` or `label` from `GET /store-api/v1/tag`.
	Tag *string `form:"tag,omitempty" json:"tag,omitempty"`

	// ProductIds Filter products by one or more product IDs. Pass multiple IDs as a comma-separated list, e.g. `<productId>,<productId>`. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/productIds`.
	ProductIds *CriteriaProductIds `form:"productIds,omitempty" json:"productIds,omitempty"`

	// CategoryId Filter products by one or more category IDs. Pass multiple IDs as a comma-separated list. Returns the products the category shows in its listing, including subcategories and categories filled by a product stream or a tag. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/categoryId`.
	CategoryId *CriteriaCategoryId `form:"categoryId,omitempty" json:"categoryId,omitempty"`

	// ManufacturerId Filter products by one or more manufacturer IDs. Pass multiple IDs as a comma-separated list. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/manufacturerId`.
	ManufacturerId *CriteriaManufacturerId `form:"manufacturerId,omitempty" json:"manufacturerId,omitempty"`

	// Properties Filter products by property values (the `id` of a value in `facets`). Pass multiple IDs as a comma-separated list. Values of the same property are combined with OR, values of different properties with AND: `properties=<11 kW>,<22 kW>,<3-phase>` returns products with 11 kW or 22 kW that are also 3-phase. `total` and the pages count the filtered products. An ID that is not a property value returns no products. A value that is not an ID returns `400` with `STROMBAUER_STORE_API__INVALID_ID/properties`.
	Properties *CriteriaProperties `form:"properties,omitempty" json:"properties,omitempty"`

	// Page Page number, starting at 1.
	Page *CriteriaPage `form:"page,omitempty" json:"page,omitempty"`

	// Limit Number of products per page. Defaults to the products-per-page setting of the shop.
	Limit *int `form:"limit,omitempty" json:"limit,omitempty"`
}

